import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ficha import *
# Guía 01 · Sepsis en Urgencias 2026 (GT-LATINFURG). 10 diapositivas. Franja azul = familia Guía.
T="GUÍA 01 · SEPSIS"; N=10; KW=dict(strip=B)
note=lambda t: f'<div style="font-size:34px;line-height:1.4;color:{G}">{t}</div>'
rows=lambda *x: '<div style="display:flex;flex-direction:column;gap:20px">'+"".join(x)+'</div>'
tag=lambda t,c=B: f'<div style="align-self:flex-start;background:{c};color:#FFF;padding:10px 22px;border-radius:8px;font-size:34px;font-weight:800;letter-spacing:4px">{t}</div>'
P=[
page(1,N,T,f'<div style="font-size:40px;font-weight:800;letter-spacing:6px;color:{B}">GUÍA 01 · URGENCIAS</div>'+big("SEPSIS 2026",200,nowrap=True)+big(f'DEL TRIAJE A LA <span style="color:{R}">UCI</span>',130)+'<div style="font-size:38px;font-weight:600;line-height:1.3;max-width:860px">Documento del GT-LATINFURG (INFURG-SEMES), publicado en Emergencias en 2026. Qué hacer en tu guardia, paso a paso.</div>',cover=True,**KW),
page(2,N,T,tag("PASO 1 · DETECTA")+big("ACTIVA EL CÓDIGO SEPSIS",100)+rows(line("Sospecha de infección y uno de estos:",True),line("qSOFA ≥ 2 · SIRS ≥ 2 · NEWS-2 ≥ 5 · qSOFA 1 con lactato ≥ 2 mmol/L"))+note("El qSOFA no debe usarse como única herramienta, ni para diagnosticar ni para pronosticar."),**KW),
page(3,N,T,tag("PASO 2 · TIEMPO CERO")+big("LACTATO Y CULTIVOS",112)+rows(line("Lactato en el triaje; si es ≥ 2 mmol/L, no alta",True),line("Repite el lactato: la tendencia importa"),line("Hemocultivos antes del antibiótico, sin retrasarlo"))+note("Ningún biomarcador aislado confirma ni descarta una sepsis."),**KW),
page(4,N,T,tag("PASO 3 · ANTIBIÓTICO",R)+big("EN 1 HORA",200,R,True)+rows(row("Shock o sepsis probable","≤ 1 h"),row("Sepsis posible, sin shock","≤ 3 h"),row("Sin foco","Ceftriaxona"),row("Shock séptico","Meropenem + vancomicina ± amikacina"))+note("Con foco conocido, la pauta del foco. Ajusta a la guía antimicrobiana de tu hospital."),**KW),
page(5,N,T,tag("PASO 4 · FLUIDOS")+big("30 ML/KG",220,R,True)+'<div style="font-size:46px;font-weight:800;line-height:1.2">De cristaloide en las 3 primeras horas si hay hipoperfusión o shock</div>'+rows(row("Tipo","Balanceado (Ringer lactato) antes que salino 0,9 %"),row("Después","Reevalúa: medidas dinámicas, relleno capilar, ecografía"))+note("Es un mínimo orientativo. Los almidones no se usan."),**KW),
page(6,N,T,tag("PASO 5 · VASOPRESOR")+big("NORADRENALINA",134,R,True)+rows(row("Preparación","10 mg en 50 ml de G5 % = 200 µg/ml"),row("Inicio","0,05–0,15 µg/kg/min"),row("Objetivo","PAM ≥ 65 mmHg"),line("Por vía periférica de buen calibre: no esperes a la central"))+note("Empieza con los fluidos si sigue hipotenso. Primera línea frente a dopamina o adrenalina."),**KW),
page(7,N,T,tag("SI PERSISTE")+big("SHOCK REFRACTARIO",120)+rows(row("Corticoide","Hidrocortisona 50 mg/6 h IV"),row("Noradrenalina al alza","Avisa a UCI"),line("No esperes a normalizar el lactato para seguir con fluidos",True))+note("El resto del soporte (vasopresina, adrenalina) es de UCI: avísala pronto."),**KW),
page(8,N,T,tag("NO LO OLVIDES")+big("CONTROLA EL FOCO",128)+rows(line("En las primeras 6 horas desde la evaluación en Urgencias",True),line("Absceso, perforación, colangitis, pielonefritis obstructiva, partes blandas necrotizantes, empiema, artritis séptica, dispositivo infectado"))+note("El antibiótico sin control del foco no resuelve la sepsis."),**KW),
page(9,N,T,tag("EVITA",R)+big("CINCO ERRORES",150)+rows(line("Cribar solo con qSOFA"),line("Esperar a la vía central para la noradrenalina"),line("Salino 0,9 % a chorro si hay balanceado"),line("Retrasar el antibiótico por esperar cultivos"),line("Dar el alta con lactato ≥ 2 mmol/L"))+note("Derivados de las recomendaciones; no son frases literales del documento."),**KW),
page(10,N,T,ficha_body("SEPSIS 2026","Adulto",[("CÓDIGO","Infección + qSOFA ≥ 2, SIRS ≥ 2 o NEWS-2 ≥ 5. qSOFA 1 + lactato ≥ 2"),("TRIAJE","Lactato (≥ 2: no alta) y hemocultivos antes del antibiótico"),("ANTIBIÓTICO","≤ 1 h (shock o probable); ≤ 3 h (posible). Sin foco: ceftriaxona. Shock: meropenem + vancomicina ± amikacina",True),("FLUIDOS","Balanceado ≥ 30 ml/kg en 3 h si hipoperfusión. Reevaluar"),("NORADREN.","10 mg/50 ml G5 %. 0,05–0,15 µg/kg/min, periférica. PAM ≥ 65"),("SI PERSISTE","Hidrocortisona 50 mg/6 h IV. Avisa a UCI",True),("FOCO","Control en ≤ 6 h")],"Julián-Jiménez A, et al. GT-LATINFURG. Emergencias 2026;38:27-63; Prescott HC, et al. Surviving Sepsis Campaign 2026 (dosis y fluidos); guía antimicrobiana HU Puerta del Mar",size=124,fs=28),ficha="01",fam="GUÍA",**KW),
]
render(P,sys.argv[1] if len(sys.argv)>1 else "out","guia-sepsis-2026")
